575	bool TestResultHelper::MatchesRegex(SQLLogicTestLogger &logger, string lvalue_str, string rvalue_str) {
576		bool want_match = StringUtil::StartsWith(rvalue_str, "<REGEX>:");
577		string regex_str = StringUtil::Replace(StringUtil::Replace(rvalue_str, "<REGEX>:", ""), "<!REGEX>:", "");
578		RE2::Options options;
579		options.set_dot_nl(true);
580		RE2 re(regex_str, options);
581		if (!re.ok()) {
582			std::ostringstream oss;
583			logger.PrintErrorHeader("Test error!");
584			logger.PrintLineSep();
585			oss << termcolor::red << termcolor::bold << "Failed to parse regex: " << re.error() << termcolor::reset
586			    << std::endl;
587			logger.LogFailure(oss.str());
588			logger.PrintLineSep();
589			return false;
590		}
591		bool regex_matches = RE2::FullMatch(lvalue_str, re);
592		if ((want_match && regex_matches) || (!want_match && !regex_matches)) {
593			return true;
594		}
595		return false;
596	}
