87	void SQLLogicTestLogger::PrintSQL() {
88		string query = sql_query;
89		if (StringUtil::EndsWith(sql_query, "\n")) {
90			// ends with a newline: don't add one
91			if (!StringUtil::EndsWith(sql_query, ";\n")) {
92				// no semicolon though
93				query[query.size() - 1] = ';';
94			}
95		} else {
96			if (!StringUtil::EndsWith(sql_query, ";")) {
97				query += ";";
98			}
99		}
100		Log("", query + "\n");
101	}
