103	void SQLLogicTestLogger::PrintSQLFormatted() {
104		std::cerr << termcolor::bold << "SQL Query" << termcolor::reset << std::endl;
105		auto tokens = Parser::Tokenize(sql_query);
106		for (idx_t i = 0; i < tokens.size(); i++) {
107			auto &token = tokens[i];
108			idx_t next = i + 1 < tokens.size() ? tokens[i + 1].start : sql_query.size();
109			// adjust the highlighting based on the type
110			switch (token.type) {
111			case SimplifiedTokenType::SIMPLIFIED_TOKEN_IDENTIFIER:
112			case SimplifiedTokenType::SIMPLIFIED_TOKEN_ERROR:
113			case SimplifiedTokenType::SIMPLIFIED_TOKEN_ERROR_EMPHASIS:
114			case SimplifiedTokenType::SIMPLIFIED_TOKEN_ERROR_SUGGESTION:
115				break;
116			case SimplifiedTokenType::SIMPLIFIED_TOKEN_NUMERIC_CONSTANT:
117			case SimplifiedTokenType::SIMPLIFIED_TOKEN_STRING_CONSTANT:
118				std::cerr << termcolor::yellow;
119				break;
120			case SimplifiedTokenType::SIMPLIFIED_TOKEN_OPERATOR:
121				break;
122			case SimplifiedTokenType::SIMPLIFIED_TOKEN_KEYWORD:
123				std::cerr << termcolor::green << termcolor::bold;
124				break;
125			case SimplifiedTokenType::SIMPLIFIED_TOKEN_COMMENT:
126				std::cerr << termcolor::grey;
127				break;
128			}
129			// print the current token
130			std::cerr << sql_query.substr(token.start, next - token.start);
131			// reset and move to the next token
132			std::cerr << termcolor::reset;
133		}
134		std::cerr << std::endl;
135	}
